CREATE TABLE IF NOT EXISTS rol(nombre VARCHAR(40) PRIMARY KEY, edicion_global BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS privilegio(nombre VARCHAR(60) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS rol_privilegio(rol VARCHAR(40) REFERENCES rol(nombre), privilegio VARCHAR(60) REFERENCES privilegio(nombre), PRIMARY KEY(rol,privilegio));
CREATE TABLE IF NOT EXISTS usuario(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario VARCHAR(60) UNIQUE NOT NULL, nombre VARCHAR(120) NOT NULL, password_hash VARCHAR(100) NOT NULL, rol VARCHAR(40) NOT NULL REFERENCES rol(nombre));
CREATE TABLE IF NOT EXISTS lote(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo VARCHAR(30) UNIQUE NOT NULL, nombre VARCHAR(120) NOT NULL, hectareas DOUBLE PRECISION NOT NULL, cultivo VARCHAR(80) NOT NULL, valle VARCHAR(80) NOT NULL, campania_cerrada BOOLEAN NOT NULL, dosis_maxima DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS labor(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, lote_id BIGINT NOT NULL REFERENCES lote(id), tipo VARCHAR(20) NOT NULL, fecha DATE NOT NULL, responsable_id BIGINT NOT NULL REFERENCES usuario(id), cantidad DOUBLE PRECISION NOT NULL, observacion VARCHAR(500) NOT NULL, creado_en TIMESTAMP NOT NULL, clave_cliente VARCHAR(100) UNIQUE);
CREATE TABLE IF NOT EXISTS configuracion(clave VARCHAR(50) PRIMARY KEY, valor VARCHAR(500) NOT NULL);
